import os, re

def load_grids_from_session():
    """Load all demo pairs and test input from the session logs"""
    d = os.path.normpath(os.environ.get('RLM_SESSION_DIR', ''))
    if not d:
        return {}

    # Find the session file
    session_file = d + '/../../sessions/' + os.path.basename(d) + '.jsonl'
    G = {}

    try:
        with open(session_file) as f:
            content = f.read()
    except:
        return {}

    # Find all demo pairs: "Demo pair X input (width)x(height):" and "Demo pair X output (width)x(height):"
    # Also "Test input (width)x(height):"
    pattern = r'(Demo pair (\d+|Test) input|Demo pair (\d+|Test) output) \((\d+)x(\d+)\):\s*\n([\s\S]*?)(?=\n(\d+ \d|Demo pair|Test input|$))'

    matches = list(re.finditer(r'(Demo pair\s+\d+\s+input|Test input) \((\d+)x(\d+)\):\s*\n', content))

    current_key = None
    rows = []

    for i, m in enumerate(re.finditer(r'(Demo pair \d+\s+input|Test input) \((\d+)x(\d+)\):\s*\n', content)):
        current_key = f"Demo pair {i} input"
        rows = []

    all_demos = []

    # Simpler approach - parse each line
    lines = content.split('\n')
    demo_idx = 0
    current_type = None
    current_rows = []
    current_w, current_h = 0, 0

    for line in lines:
        if re.match(r'Demo pair \d+ (input|output) \(\d+x\d+\):', line):
            # Save previous if exists
            if current_type and current_rows:
                all_demos.append((current_type, current_rows))
                current_type = None
            demo_idx += 1

            match = re.match(r'(Demo pair \d+ |Test )(\w+)\s*\((\d+)x(\d+)\):', line)
            if match:
                current_type = match.group(2)
                current_w, current_h = int(match.group(3)), int(match.group(4))
                current_rows = []

        elif current_type and current_rows:
            current_rows.append(line)

    # Save last
    if current_type and current_rows:
        all_demos.append((current_type, current_rows))

    for idx, (ptype, rows) in enumerate(all_demos):
        if ptype == 'input':
            img_name = f"input_{idx}"
        else:
            img_name = f"output_{idx}"

        grid = [[int(x) for x in re.findall(r'\d+', r)] for r in rows]
        G[img_name] = grid

    return G

